# mark_done and remove raise TodoNotFoundError(todo_id) and leave the file
# unchanged when no todo has that id. mark_done on an already-done todo succeeds.

@app.command()
def done(todo_id: int) -> None:
    """Mark a todo done."""
    try:
        todo = _store().mark_done(todo_id)
    except TodoNotFoundError:
        typer.echo(f"Error: no todo with id {todo_id}", err=True)
        raise typer.Exit(1) from None
    typer.echo(f"Done {todo.id}: {todo.text}")
